package net.officefloor.hq.app.person;


/** A person as the screen shows them, with their grade in force on the sheet's today, their statement count and
 *  the last statement's due-total (two decimals; null when n/a, or none taken) and date (yyyy-mm-dd; null when none
 *  taken), the date they are retired from (yyyy-mm-dd; null: not retired), whether they have any hold, their dated
 *  grades, earliest first (each from its from-date, yyyy-mm-dd; null: from the beginning of time), and their holds
 *  in the order they were put on (from- and to-date, yyyy-mm-dd; null: unbounded on that side), their own terms in days (null: none), their contact (null: none), their aliases, sorted as
 *  names are compared, whether their name or an alias is also used on another sheet of their sheet's tree, and the
 *  sheet they were last transferred from (null: never transferred), and their past retirements, in the order they
 *  ended, and their tags, sorted (empty when none). */
public record PersonResponse(long id, String name, String grade, long version, int statementCount,
        String statedTotal, String statementDate, String retiredFrom, boolean held, List<GradeResponse> grades,
        List<HoldResponse> holds, Integer terms, String contact, List<String> aliases,
        boolean clashing, String origin, List<RetirementResponse> retirements, List<String> tags) {

    /** A past retirement from a from-date to the day they were unretired (yyyy-mm-dd). */
    public record RetirementResponse(String from, String to) {
    }

    /** A grade given from a from-date (yyyy-mm-dd; null: from the beginning of time). */
    public record GradeResponse(String grade, String from) {
    }

    /** A hold from a from-date to a to-date (yyyy-mm-dd; null: unbounded on that side). */
    public record HoldResponse(String from, String to) {
    }

    public static PersonResponse from(Person p) {
        return from(p, false);
    }

    public static PersonResponse from(Person p, boolean clashing) {
        return new PersonResponse(p.id(), p.name(), p.grade(), p.version(), p.statementCount(),
                p.statedTotal() != null ? p.statedTotal().toPlainString() : null,
                p.statementDate() != null ? p.statementDate().toString() : null,
                p.retiredFrom() != null ? p.retiredFrom().toString() : null, p.holds().any(),
                p.grades().history().stream()
                        .map(g -> new GradeResponse(g.grade(), g.from() != null ? g.from().toString() : null)).toList(),
                p.holds().history().stream().map(h -> new HoldResponse(h.from() != null ? h.from().toString() : null,
                        h.to() != null ? h.to().toString() : null)).toList(), p.terms(), p.contact(), p.aliases(),
                clashing, p.origin(), p.retirements().stream()
                        .map(r -> new RetirementResponse(r.from().toString(), r.to().toString())).toList(),
                p.tags() != null ? List.of(p.tags().split(",")) : List.of());
    }
}
package net.officefloor.hq.app.person;


/** The sheet's people, in the order they were added (as they stood at the end of the as-of date, when one is given). */
public class RespondWithPeople {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, PersonRepository repository,
            ObjectResponse<List<PersonResponse>> response) {
        String id = sheetId.trim();
        LocalDate end = AsOf.parse(asOf);
        List<Person> people = end != null ? repository.listAsOf(id, end) : repository.list(id);
        List<String> tree = repository.tree(id);
        response.send(people.stream().map(p -> PersonResponse.from(p, repository.clashing(p, tree))).toList());
    }
}
package net.officefloor.hq.app.claim;


/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-mm-dd, the status, its
 *  number (null when it has none) and the due fixed when it was settled (two decimals; null when it is not
 *  settled, or its grade had no rate then, so its due follows the rates), who opened it (null while a draft),
 *  whether its person's last statement bound it and the figure it bound it to (two decimals; null when not
 *  bound, or n/a then), and the number a correction corrects (null when it is not one), and its due-by as yyyy-mm-dd,
 *  and its status log, oldest first (empty when not loaded with it), and the date it is deferred until as yyyy-mm-dd
 *  (null when never deferred) and whether it is deferred on the sheet's today (see Claim.deferredOn; false when
 *  shown without a today), and its proofs count, and the number of the claim it was split from (null when
 *  it was not split off one), and whether it is a late entry, and the last day it was reminded as yyyy-mm-dd (null when never), and its external reference (null when none), and its tags, sorted (empty when none), and its comments, oldest first, as <user> on <date>: <text> (empty when not
 *  loaded with them), and the number of the settle batch that settled it (null when none settled it), and its lines, in the
 *  order added, as <label> <qty> x <unit> (empty when not loaded with them). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        List<String> log, String deferredUntil, boolean deferred, int proofs, String splitFrom, boolean lateEntry, String reminded, String ref,
        List<String> tags, List<String> comments, Integer batch, List<String> lines) {
    public static ClaimResponse from(Claim c) {
        return from(c, List.of(), null);
    }

    public static ClaimResponse from(Claim c, List<String> log, LocalDate today) {
        return from(c, log, today, List.of());
    }

    public static ClaimResponse from(Claim c, List<String> log, LocalDate today, List<String> comments) {
        return from(c, log, today, comments, null);
    }

    public static ClaimResponse from(Claim c, List<String> log, LocalDate today, List<String> comments,
            Integer batch) {
        return from(c, log, today, comments, batch, List.of());
    }

    public static ClaimResponse from(Claim c, List<String> log, LocalDate today, List<String> comments,
            Integer batch, List<String> lines) {
        return new ClaimResponse(c.id(), c.personId(), c.amount().toPlainString(), c.date().toString(), c.note(),
                c.status().name(), c.number(), c.settledDue() != null ? c.settledDue().toPlainString() : null,
                c.openedBy(), c.stated(), c.statedDue() != null ? c.statedDue().toPlainString() : null,
                c.corrects(), c.dueBy().toString(), log,
                c.deferredUntil() != null ? c.deferredUntil().toString() : null, c.deferredOn(today), c.proofs(),
                c.splitFrom(), c.lateEntry(), c.reminded() != null ? c.reminded().toString() : null, c.ref(),
                c.tags() != null ? List.of(c.tags().split(",")) : List.of(), comments, batch, lines);
    }
}
package net.officefloor.hq.app.claim;


/** The sheet's claims, newest first, each with its status log and its comments and its lines and whether it is deferred on the sheet's today and the settle batch that settled it; given
 *  an as-of date, as they stood at the end of it, with their logs and comments then and deferred on it. */
public class RespondWithClaims {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, ClaimRepository repository,
            ClaimLogRepository logs, ClaimCommentRepository comments, ClaimLineRepository claimLines, SheetRepository sheets, SettleBatchRepository batches,
            ObjectResponse<List<ClaimResponse>> response) {
        String id = sheetId.trim();
        LocalDate end = AsOf.parse(asOf);
        Map<Long, List<String>> lines = logs.lines(id, end);
        Map<Long, List<String>> said = comments.lines(id, end);
        Map<Long, List<String>> lined = claimLines.lines(id, end);
        Map<Long, Integer> settledBy = batches.byClaim(id);
        var today = end != null ? end : sheets.today(id);
        List<Claim> claims = end != null ? repository.listAsOf(id, end) : repository.list(id);
        response.send(claims.stream()
                .map(c -> ClaimResponse.from(c, lines.getOrDefault(c.id(), List.of()), today,
                        said.getOrDefault(c.id(), List.of()), batchOf(c, settledBy),
                        lined.getOrDefault(c.id(), List.of()))).toList());
    }

    /** The batch that settled the claim, shown while it is PENDING or SETTLED; null otherwise. */
    private static Integer batchOf(Claim c, Map<Long, Integer> settledBy) {
        return c.status() == ClaimStatus.PENDING || c.status() == ClaimStatus.SETTLED ? settledBy.get(c.id()) : null;
    }
}
package net.officefloor.hq.app.statement;


/** Claim figures and due-totals, as the screen shows them. */
public final class Dues {
    private Dues() {
    }

    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to, n/a
     *  included (not while it is PENDING: then it is live), else live: its amount times its person's rate in force on
     *  its date for their grade then, divided by 100, rounded to two decimals as the claim rounds (see Rounding); null
     *  (n/a) when no rate applies. The floor is not in it: it is applied last (see shown). */
    public static BigDecimal figure(Claim claim, Grades grades, Rates rates, Rounding rounding) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        return live(claim, grades, rates, rounding);
    }

    /** A claim's due as its row shows it: the due fixed when it was settled, else the greater of the floor in force
     *  on its date and its figure (bound or live) with the late charge on it added (a correction, a negative amount,
     *  has no floor and no charge); null (n/a) when it has no figure. */
    public static BigDecimal shown(Claim claim, Grades grades, Rates rates, DatedAmount floor,
            LateCharge late) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        BigDecimal figure = figure(claim, grades, rates, late.rounding());
        if (figure == null || claim.amount().signum() < 0) {
            return figure;
        }
        return figure.add(late.on(claim, figure)).max(floor.on(claim.date()));
    }

    /** A claim's live figure: its amount times its person's rate in force on its date for their grade then, divided
     *  by 100, rounded to two decimals as the claim rounds (see Rounding); null (n/a) when no rate applies. */
    public static BigDecimal live(Claim claim, Grades grades, Rates rates, Rounding rounding) {
        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date())
                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)))
                .orElse(null);
    }

    /** Whether a claim counts toward its person's figures and every live total: an OPEN, PENDING or SETTLED one,
     *  except an OPEN one dated within one of its person's holds and not bound by a statement, an OPEN or PENDING one
     *  not bound by a statement once its person's retirement date is reached (see retiredOut), and one deferred on the
     *  sheet's today (see Claim.deferredOn). */
    public static boolean counts(Claim claim, Holds holds, LocalDate retiredFrom, LocalDate today) {
        return claim.status().counts() && !claim.deferredOn(today)
                && !(claim.status() == ClaimStatus.OPEN && !claim.stated() && holds.covers(claim.date()))
                && !retiredOut(claim, retiredFrom, today);
    }

    /** Whether a claim leaves the live totals because its person is retired: the sheet's today is on or after their
     *  retirement date (null: not retired) and it is OPEN or PENDING and not bound by a statement. */
    private static boolean retiredOut(Claim claim, LocalDate retiredFrom, LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom) && !claim.stated()
                && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING);
    }

    /** Whether a claim counts toward a period's due-totals: its status at the end of the period's last day (see
     *  ClaimLogRepository.statusesAt; null: it was added after) is OPEN, PENDING or SETTLED, and it is left out
     *  as the live rules leave it out: deferred on the sheet's today, or an OPEN one dated within one of its
     *  person's holds and not bound by a statement, or an OPEN or PENDING one of a retired person (see counts). */
    public static boolean countsAtEnd(Claim claim, ClaimStatus atEnd, Holds holds, LocalDate retiredFrom,
            LocalDate today) {
        return atEnd != null && atEnd.counts() && !claim.deferredOn(today)
                && !(claim.status() == ClaimStatus.OPEN && !claim.stated() && holds.covers(claim.date()))
                && !retiredOut(claim, retiredFrom, today);
    }

    /** A person's due-total: the dues (as shown) of their claims that count added up, skipping n/a; null (n/a) when
     *  their grade today has no rate today, unless a claim that counts has a figure (settled, stated, or live at
     *  the grade in force on its date). */
    public static BigDecimal total(String sheetId, List<Claim> claims, Grades grades, Holds holds,
            LocalDate retiredFrom, LocalDate today, Rates rates, DatedAmount floor, LateCharge late) {
        List<Claim> counted = claims.stream().filter(c -> counts(c, holds, retiredFrom, today)).toList();
        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
                .filter(f -> f != null).toList();
        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
            return null;
        }
        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
    }

    /** A due-total at most the sheet's cap (null: none); n/a (null) is not capped. */
    public static BigDecimal capped(BigDecimal total, BigDecimal cap) {
        return total != null && cap != null ? total.min(cap) : total;
    }
}
package net.officefloor.hq.app.statement;


/** How the sheet rounds a claim's live figures: by its policy date (the policy-date setting, else the sheet's today;
 *  null: none, everything rounds half to even), and the dates of its numbered claims (a correction rounds by the
 *  date of the claim it corrects). */
public record Rounding(LocalDate policy, Map<String, LocalDate> numbered) {

    /** The sheet's rounding as it is now. */
    public static Rounding of(String sheetId, SettingRepository settings, SheetRepository sheets,
            ClaimRepository claims) {
        LocalDate policy = settings.policyDate(sheetId);
        Map<String, LocalDate> numbered = new HashMap<>();
        for (Claim c : claims.list(sheetId)) {
            if (c.number() != null) {
                numbered.put(c.number(), c.date());
            }
        }
        return new Rounding(policy != null ? policy : sheets.today(sheetId), numbered);
    }

    /** Every figure rounded half to even. */
    public static Rounding none() {
        return new Rounding(null, Map.of());
    }

    /** How a claim's live figures round: half up when it (a correction: the claim it corrects) is dated before the
     *  policy date, else half to even. */
    public RoundingMode of(Claim claim) {
        LocalDate date = claim.corrects() != null ? numbered.getOrDefault(claim.corrects(), claim.date())
                : claim.date();
        return policy != null && date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
package net.officefloor.hq.app.statement;


/** The sheet's late charge as it is today: its late percent by date (a claim gains the one in force on each 30-day boundary past its due-by plus its grace; a claim is overdue past its own due-by, fixed when
 *  it was created, plus its grace) and its today (null: none, so nothing is overdue) and each claim's grace (days: the
 *  grace in force on its date of its person's grade in force on that date; 0 when none). */
public record LateCharge(DatedAmount pct, LocalDate today, Rounding rounding, Grace grace) {

    /** A claim's grace, in days. */
    @FunctionalInterface
    public interface Grace {
        int of(Claim claim);

        /** No grace for any claim. */
        Grace NONE = claim -> 0;

        /** The grace of the grade in force on a claim's date (its person's, by id, in `grades`) in force on that date,
         *  in the history. */
        static Grace of(SettingHistory history, Map<Long, Grades> grades) {
            return claim -> history.graceFor(grades.getOrDefault(claim.personId(), Grades.NONE).on(claim.date()),
                    claim.date());
        }
    }

    /** The sheet's late charge as it is now. */
    public static LateCharge of(String sheetId, SettingRepository settings, SheetRepository sheets,
            ClaimRepository claims, PersonRepository people) {
        Map<Long, Grades> grades = people.list(sheetId).stream()
                .collect(Collectors.toMap(Person::id, Person::grades, (a, b) -> a));
        return new LateCharge(settings.latePct(sheetId), sheets.today(sheetId),
                Rounding.of(sheetId, settings, sheets, claims), Grace.of(settings.history(sheetId), grades));
    }

    /** No late charge at all. */
    public static LateCharge none() {
        return new LateCharge(DatedAmount.always(BigDecimal.ZERO), null, Rounding.none(), Grace.NONE);
    }

    /** The day a claim's late charge counts from: its due-by plus its grace. */
    public LocalDate lateFrom(Claim claim) {
        return claim.dueBy().plusDays(grace.of(claim));
    }

    /** Whether a claim is overdue: it is OPEN or PENDING, not deferred on today, and its due-by plus its grace is
     *  before today. */
    public boolean overdue(Claim claim) {
        return claim.status().unsettled() && today != null && !claim.deferredOn(today)
                && lateFrom(claim).isBefore(today);
    }

    /** The charge on a claim whose figure is `figure`: for each full 30 days it is overdue, the late percent in force
     *  on that boundary date (its due-by plus its grace plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it (compounding), each
     *  rounded to two decimals as the claim rounds (see Rounding), the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not
     *  overdue, or it is a correction (a negative amount). */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        BigDecimal total = new BigDecimal("0.00");
        if (!overdue(claim) || claim.amount().signum() < 0) {
            return total;
        }
        LocalDate from = lateFrom(claim);
        long periods = ChronoUnit.DAYS.between(from, today) / 30;
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = this.pct.on(from.plusDays(30 * n));
            if (pct.signum() != 0) {
                total = total.add(figure.add(total).multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)));
            }
        }
        return total;
    }
}
package net.officefloor.hq.app.claim;


/** The terms a new claim is fixed with when it is created, and the due-by they give; a claim belongs to the period
 *  holding its due-by. */
public final class DueBy {

    private DueBy() {
    }

    /** The terms (business days) a new claim of the person dated on the date is fixed with: the person's own terms,
     *  else the terms of their grade in force on the date (else the sheet's terms in force on it). */
    public static int terms(Person person, LocalDate date, SettingRepository settings) {
        return person.terms() != null ? person.terms()
                : settings.termsFor(person.sheetId(), person.grades().on(date), date);
    }

    /** The due-by of a new claim of the person dated on the date: the terms-th business day after the date, skipping
     *  Saturdays, Sundays and the sheet's holidays as they are now. */
    public static LocalDate of(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.dueBy(person.sheetId(), date, terms(person, date, settings));
    }
}
package net.officefloor.hq.app.claim;


/** Tags as claims and people carry them. */
public final class Tags {
    private Tags() {
    }

    /** Tags as typed, separated by commas: each trimmed and lower-cased, blanks and repeats dropped, sorted and joined
     *  by commas ("" when none). */
    public static String normalise(String typed) {
        return Arrays.stream(typed.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
                .distinct().sorted().collect(Collectors.joining(","));
    }
}
package net.officefloor.hq.app.person;


/** A person's holds, in the order they were put on: each runs from its from-date (null: from the beginning of time)
 *  to its to-date (null: open-ended), both included. */
public record Holds(List<Hold> history) {

    /** A hold from a from-date to a to-date (either null: unbounded on that side). */
    public record Hold(LocalDate from, LocalDate to) {
        boolean covers(LocalDate date) {
            return (from == null || !from.isAfter(date)) && (to == null || !to.isBefore(date));
        }
    }

    public static final Holds NONE = new Holds(List.of());

    /** Whether the person has any hold. */
    public boolean any() {
        return !history.isEmpty();
    }

    /** Whether a hold covers the date. */
    public boolean covers(LocalDate date) {
        return history.stream().anyMatch(h -> h.covers(date));
    }
}
package net.officefloor.hq.app.person;


/** A person's dated grades, earliest first: each applies from its from-date (null: from the beginning of time). */
public record Grades(List<Grade> history) {

    /** A grade given from a from-date (null: from the beginning of time). */
    public record Grade(String grade, LocalDate from) {
        boolean appliesOn(LocalDate date) {
            return from == null || !from.isAfter(date);
        }
    }

    public static final Grades NONE = new Grades(List.of());

    /** The grade in force on the date: the one whose from-date is the latest on or before it; "" when none applies. */
    public String on(LocalDate date) {
        return history.stream().filter(g -> g.appliesOn(date))
                .max(Comparator.comparing(Grade::from, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(Grade::grade).orElse("");
    }
}

