/** A person on a sheet: a name and a grade (A, B or C: the one in force on the sheet's today), the version stored (one more on each edit), how many
 *  statements have been taken of them, and the last one's due-total (null when n/a, or none taken) and date
 *  (the sheet's today then; null when none taken), the date they are retired from (null: not retired), whether
 *  they have any hold, their dated grades, earliest first, and their holds in the order they were put on (their OPEN
 *  claims dated within one, not bound by a statement, count in no live total), their own terms in days (null: none), their contact (trimmed, lower-cased; null: none), their aliases, sorted as names are compared, and whether their name or an alias is also used on another
 *  sheet of the sheet's tree (its ancestors and descendants), the sheet they were last transferred from (null:
 *  never transferred), and their past retirements, in the order they were unretired, and their tags (trimmed, lower-cased,
 *  without repeats), sorted (empty when none). */
export type Person = { id: number; name: string; grade: string; version: number; statementCount: number;
  statedTotal: string | null; statementDate: string | null; retiredFrom: string | null; held: boolean;
  grades: Grade[]; holds: Hold[]; terms: number | null;
  contact: string | null; aliases: string[]; clashing: boolean; origin: string | null;
  retirements: Retirement[]; tags: string[] };

/** A past retirement, from the date they were retired from to the day they were unretired (yyyy-mm-dd). */
export type Retirement = { from: string; to: string };

/** A hold on a person, from its from-date to its to-date, both included (yyyy-mm-dd, or null: unbounded on that side). */
export type Hold = { from: string | null; to: string | null };

/** Whether one of the person's holds covers the date (yyyy-mm-dd). */
export function heldOn(person: Person | undefined, date: string): boolean {
  return (person?.holds ?? []).some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
}

/** Whether the person's retirement date is reached on the sheet's today (yyyy-mm-dd; '' while loading: not reached):
 *  from then their OPEN and PENDING claims not bound by a statement count in no live total. */
export function retiredOn(person: Person | undefined, today: string): boolean {
  return today !== '' && person?.retiredFrom != null && person.retiredFrom <= today;
}

/** A grade a person was given, in force from its from-date (yyyy-mm-dd, or null: from the beginning of time). */
export type Grade = { grade: string; from: string | null };

/** The person's grade in force on a date (yyyy-mm-dd): the one whose from-date is the latest on or before it,
 *  a grade with no from-date applying from the beginning of time; '' when none applies. */
export function gradeOn(person: Person | undefined, date: string): string {
  let found: Grade | undefined;
  for (const g of person?.grades ?? []) {
    if (g.from !== null && g.from > date) continue;
    if (!found || (found.from ?? '') <= (g.from ?? '')) found = g;
  }
  return found?.grade ?? '';
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

/** The query of the sheet's people, in list order (by their position; new people go to the end). */
export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
});

/** The sheet's people, in list order (by their position; new people go to the end). */
export function usePeople(sheetId: string) {
  return useQuery(peopleQuery(sheetId));
}

/** The id of the person whose editor is open ('' when the form adds a new person). */
export function useEditingPerson() {
  return useSearchParam('editPerson', asString);
}

/** Close the person's editor, when it is still theirs that is open (another may have been opened since). */
export function useCloseEditor() {
  const navigate = useNavigate();
  return (personId: number) =>
    void navigate({
      to: '.',
      search: (prev: Record<string, unknown>) => {
        if (prev.editPerson !== String(personId)) return prev;
        const next = { ...prev };
        delete next.editPerson;
        return next;
      },
      replace: true,
    });
}

/** Whether retired people are listed: off when the screen is first opened, and left as it is by loading a sheet. */
export function useShowRetired() {
  return useSearchParam('showRetired', asFlag);
}

/** The sheet's settings: the clerk limit with two decimals ('' when there is none) and the floor with two
 *  decimals (a claim's live due is at least it), and the terms in business days (a claim's due-by is the terms-th business day after its date: not a Saturday, Sunday or holiday), and
 *  the late percent with two decimals (an overdue claim gains, of its figure, the one in force on each full 30-day boundary past its due-by), and the
 *  policy date (yyyy-mm-dd; '' when blank: the sheet's today) a claim's live figures round by, and the period numbering from (yyyy-mm-dd; '' when off: on or after it, by
 *  the sheet's today, a claim opened is numbered within its period), and each grade's own terms in days ('' when the
 *  grade has none: it uses the sheet's terms), and the cap with two decimals ('' when there is none: a person's
 *  due-total is at most it), and the proof threshold with two decimals ('' when there is none: a claim whose due is
 *  above the one in force on its date cannot be settled or approved without a proof), and the note threshold with two decimals ('' when there is none: a
 *  claim whose due is above the one in force on its date cannot be opened with an empty note). A claim's terms are fixed when it is created. Each is the value in force on the sheet's
 *  today; `dated` holds every value recorded for the settings that carry a figure, by key (clerk-limit, floor, terms,
 *  terms-A/B/C, late-pct, cap, proof-threshold, proof-threshold-A/B/C, note-threshold), oldest from-date first. `perms` is the permission matrix (not dated): for
 *  each action the roles that may take it, comma separated ('' when blank: the standing rule). `graceDays` is the grace days (not dated; '' when off): when the sheet's
 *  today is changed, each open period whose to-date plus them is before the new today is closed. `entryDate` is the entry date (not dated; '' when off): while it is set, a new claim
 *  given no date is dated it instead of the sheet's today. `gradeGrace` is each grade's grace in days ('' when the grade
 *  has none), dated (keys grace-A/B/C): a claim whose person's grade in force on its date has a grace in force on that
 *  date is overdue, and counts its late charge, from its due-by plus it. `gradeProofThreshold` is each grade's own proof
 *  threshold with two decimals ('' when the grade has none: the sheet's applies), dated (keys proof-threshold-A/B/C). `pot` is the pot
 *  with two decimals (not dated; '' when there is none): each member of a balanced pool is shown their cut of it. `parent` is
 *  the parent sheet's id (not dated; '' when there is none): a grade with no rate in force on a date on this sheet takes
 *  the parent's rate for it on that date, then the parent's parent's, up to three levels up. `fiscalStartMonth` is the
 *  month (1 to 12, not dated; 1 unless set) a fiscal year starts on the first day of (see fiscalYearOf). `alertThreshold`
 *  is the alert threshold with two decimals (not dated; '' when off): a person whose due-total crosses above it over a
 *  change is alerted in the audit file. */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string;
  periodNumberingFrom: string; gradeTerms: Record<string, string>; cap: string; proofThreshold?: string; noteThreshold?: string; dated?: Record<string, Dated[]>;
  perms?: Record<string, string>; graceDays?: string; entryDate?: string; gradeGrace?: Record<string, string>;
  gradeProofThreshold?: Record<string, string>; pot?: string; parent?: string; fiscalStartMonth?: string; alertThreshold?: string };

/** A dated setting's value ('' when blank) in force from its from-date (yyyy-mm-dd). */
export type Dated = { from: string; value: string };

/** A dated figure as it applies to a date (yyyy-mm-dd): the value in force on it. */
export type DatedValue = (date: string) => string;

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it, else the
 *  sheet's starting value. */
export function valueOn(values: Dated[] | undefined, start: string, date: string): string {
  let found: Dated | undefined;
  for (const v of values ?? []) {
    if (v.from <= date && (!found || found.from < v.from)) found = v;
  }
  return found ? found.value : start;
}

/** The actions the permission matrix covers, in order. */
export const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;

/** The grades that may have terms of their own. */
export const GRADES = ['A', 'B', 'C'] as const;

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days. */
export const DEFAULT_TERMS = '14';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The sheet's settings as they are now. */
export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/** The sheet's parent sheet id ('' when there is none, or while the settings load). */
export function useParent(sheetId: string): string {
  return useSettings(sheetId).data?.parent ?? '';
}

/** The sheet's fiscal year start month, 1 to 12 (1 while the settings load). */
export function useFiscalStartMonth(sheetId: string): number {
  return Number(useSettings(sheetId).data?.fiscalStartMonth || '1');
}

/** The fiscal year a date (yyyy-mm-dd) falls in, FY<yyyy>: named by the calendar year of the fiscal year's first day,
 *  the first of the start month on or before the date. */
export function fiscalYearOf(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

/** The sheet's floor by date: a claim's live due is at least the one in force on its date (the starting floor
 *  while the settings load). */
export function useFloor(sheetId: string): DatedValue {
  const settings = useSettings(sheetId).data;
  return useMemo(() => floorOf(settings), [settings]);
}

/** The sheet's cap in force ('' when there is none, or while the settings load). */
export function useCap(sheetId: string): string {
  return useSettings(sheetId).data?.cap ?? '';
}

/** The sheet's terms in force, in days (the starting terms while the settings load). */
export function useTerms(sheetId: string): number {
  return Number(useSettings(sheetId).data?.terms ?? DEFAULT_TERMS);
}

/** The floor by date from a sheet's settings: the one in force on a date (the starting floor while they load). */
export function floorOf(settings: Settings | undefined): DatedValue {
  const dated = settings?.dated?.floor;
  return (date: string) => valueOn(dated, DEFAULT_FLOOR, date);
}

/** What the late charge follows (see useLate), from a sheet's settings, its today, its claims and its people. */
export function lateOf(settings: Settings | undefined, today: string, claims: Claim[] | undefined,
    people: Person[] | undefined): Late {
  const numbered = new Map((claims ?? []).filter((c) => c.number !== null).map((c) => [c.number as string, c.date]));
  const dated = settings?.dated?.['late-pct'];
  const pct = (date: string) => valueOn(dated, DEFAULT_LATE_PCT, date);
  const byId = new Map((people ?? []).map((p) => [p.id, p]));
  const history = settings?.dated;
  const grace = (claim: Claim) => {
    const grade = gradeOn(byId.get(claim.personId), claim.date);
    if (grade === '') return 0;
    const days = valueOn(history?.[`grace-${grade}`], '', claim.date);
    return days === '' ? 0 : Number(days);
  };
  return { pct, today, grace, policy: settings?.policyDate || today, numbered };
}

/** What the late charge follows now: the late percent by date (a claim gains the one in force on its date) and the sheet's today, and each
 *  claim's grace (of its person's grade on its date, in force on that date; 0 while loading); and how claims round:
 *  the policy date in force (blank: the sheet's today) and the dates of the sheet's numbered claims. */
export function useLate(sheetId: string): Late {
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId);
  const claims = useClaims(sheetId).data;
  const people = usePeople(sheetId).data;
  return useMemo(() => lateOf(settings, today, claims, people), [settings, today, claims, people]);
}
package net.officefloor.hq.app.claim;


/** The rules of a claim's status change and its audit line, shared by a single change ({@link SaveClaimStatus},
 *  {@link AuditClaimStatus}) and a bulk settle ({@link BulkSettleClaims}). */
final class ClaimStatusChange {
    private ClaimStatusChange() {
    }

    /** How many days after its settlement (by the sheet's today, as its status log records it) a steward may still
     *  void a SETTLED claim. */
    private static final int VOID_SETTLED_DAYS = 7;

    /** Move the claim to its new status as {@link SaveClaimStatus} describes, adding it to its status log: the claim
     *  as stored now; throws (having written nothing) when the change is not allowed. */
    static ClaimResponse save(ClaimStatusInput input, Claim loaded, ClaimRepository repository,
            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
            SheetRepository sheets, ClaimLogRepository log)
            throws ClaimStatusNotAllowedException {
        ClaimStatus to = check(input, loaded, repository, people, rates, roles, settings, sheets, log);
        boolean opening = input.action().equals("open");
        String openedBy = opening ? input.user() : loaded.openedBy();
        String number = opening ? repository.nextNumber(loaded.sheetId(), loaded.dueBy()) : loaded.number();
        BigDecimal settledDue = input.action().equals("resettle")
                ? dueNow(asOpenUnstated(loaded), repository, people, rates, settings, sheets)
                : to == ClaimStatus.SETTLED ? dueNow(loaded, repository, people, rates, settings, sheets)
                : to == ClaimStatus.VOID && loaded.status() == ClaimStatus.SETTLED ? loaded.settledDue() : null;
        if (!repository.changeStatus(loaded, to, number, settledDue, openedBy)) {
            // the transaction rolls back, so a number taken above is not used up
            throw new ClaimStatusNotAllowedException(loaded.status(), to);
        }
        log.record(loaded, input.user());
        return ClaimResponse.from(new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), loaded.amount(),
                loaded.date(), loaded.note(), to, number, settledDue, openedBy, loaded.stated(),
                loaded.statedDue(), loaded.corrects(), loaded.dueBy(), loaded.deferredUntil(), loaded.proofs(), loaded.splitFrom(), loaded.lateEntry(), loaded.reminded(), loaded.ref(), loaded.tags()));
    }

    /** The status the claim would move to by the change as {@link SaveClaimStatus} describes (PENDING for a clerk's
     *  settle above the clerk limit), writing nothing; throws when the change is not allowed. */
    static ClaimStatus check(ClaimStatusInput input, Claim loaded, ClaimRepository repository,
            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
            SheetRepository sheets, ClaimLogRepository log)
            throws ClaimStatusNotAllowedException {
        ClaimStatus to = input.to();
        if (Permissions.ACTIONS.contains(input.action()) && !settings.permissions(loaded.sheetId())
                .allows(input.action(), roles.of(loaded.sheetId(), input.user()))) {
            throw new ClaimStatusNotAllowedException("Your role may not " + input.action() + " a claim on this sheet.");
        }
        boolean review = input.action().equals("approve") || input.action().equals("reject");
        if (review) {
            if (loaded.status() != ClaimStatus.PENDING) {
                throw new ClaimStatusNotAllowedException("Only a PENDING claim can be " + input.action()
                        + "d; this one is " + loaded.status() + ".");
            }
            if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
                throw new ClaimStatusNotAllowedException("Only a steward can " + input.action() + " a PENDING claim.");
            }
            if (input.action().equals("approve") && input.user().equals(loaded.openedBy())) {
                throw new ClaimStatusNotAllowedException("The user who opened a claim cannot approve it.");
            }
            if (input.action().equals("approve") && input.user().equals(repository.editedBy(loaded))) {
                throw new ClaimStatusNotAllowedException("The user who last edited a claim cannot approve it.");
            }
        } else if (input.action().equals("resettle")) {
            if (loaded.status() != ClaimStatus.SETTLED) {
                throw new ClaimStatusNotAllowedException("Only a SETTLED claim can be re-settled; this one is "
                        + loaded.status() + ".");
            }
            if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
                throw new ClaimStatusNotAllowedException("Only a steward can re-settle a claim.");
            }
        } else if (input.action().equals("void") && loaded.status() == ClaimStatus.SETTLED) {
            if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
                throw new ClaimStatusNotAllowedException("Only a steward can void a SETTLED claim.");
            }
            LocalDate settledOn = log.lastOn(loaded.sheetId(), loaded.id(), ClaimStatus.SETTLED);
            LocalDate today = sheets.today(loaded.sheetId());
            if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
                throw new ClaimStatusNotAllowedException("A SETTLED claim can only be voided within "
                        + VOID_SETTLED_DAYS + " days of its settlement.");
            }
        } else if (input.action().equals("restore")) {
            if (loaded.status() != ClaimStatus.DELETED) {
                throw new ClaimStatusNotAllowedException("Only a DELETED claim can be restored; this one is "
                        + loaded.status() + ".");
            }
            LocalDate deletedOn = log.lastOn(loaded.sheetId(), loaded.id(), ClaimStatus.DELETED);
            LocalDate today = sheets.today(loaded.sheetId());
            if (deletedOn == null || !deletedOn.equals(today)) {
                throw new ClaimStatusNotAllowedException("A DELETED claim can only be restored on the day it was deleted.");
            }
        } else if (!loaded.status().canBecome(to)) {
            throw new ClaimStatusNotAllowedException(loaded.status(), to);
        }
        if (input.action().equals("settle") && loaded.deferredOn(sheets.today(loaded.sheetId()))) {
            throw new ClaimStatusNotAllowedException("This claim is deferred until " + loaded.deferredUntil()
                    + "; it cannot be settled before then.");
        }
        if (input.action().equals("settle") && input.user().equals(loaded.openedBy())) {
            throw new ClaimStatusNotAllowedException("The user who opened a claim cannot settle it.");
        }
        if (input.action().equals("settle") && input.user().equals(repository.editedBy(loaded))) {
            throw new ClaimStatusNotAllowedException("The user who last edited a claim cannot settle it.");
        }
        if ((input.action().equals("settle") || input.action().equals("approve")) && loaded.proofs() == 0) {
            var person = people.find(loaded.sheetId(), loaded.personId());
            String grade = person != null ? person.grades().on(loaded.date()) : null;
            BigDecimal threshold = settings.proofThresholdFor(loaded.sheetId(), grade, loaded.date());
            BigDecimal due = dueNow(loaded, repository, people, rates, settings, sheets);
            if (threshold != null && due != null && due.compareTo(threshold) > 0) {
                throw new ClaimStatusNotAllowedException("This claim's due " + due + " is above the proof threshold "
                        + threshold + "; add a proof before it is " + input.action() + "d.");
            }
        }
        if (input.action().equals("open")) {
            String refused = noteRequired(loaded, repository, people, rates, settings, sheets);
            if (refused != null) {
                throw new ClaimStatusNotAllowedException(refused);
            }
        }
        if (input.action().equals("settle") && Role.CLERK.equals(roles.of(loaded.sheetId(), input.user()))) {
            BigDecimal limit = settings.clerkLimit(loaded.sheetId());
            BigDecimal due = dueNow(loaded, repository, people, rates, settings, sheets);
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                to = ClaimStatus.PENDING;
            }
        }
        return to;
    }

    /** Record the stored status change in the audit file as {@link AuditClaimStatus} describes. */
    static void audit(ClaimStatusInput input, Claim loaded, ClaimResponse saved, PersonRepository people,
            WatchRepository watches, Audit audit) {
        var person = people.find(loaded.sheetId(), loaded.personId());
        String event = switch (input.action()) {
            case "open" -> "CLAIM_OPENED";
            case "settle" -> "PENDING".equals(saved.status()) ? "CLAIM_PENDING" : "CLAIM_SETTLED";
            case "approve" -> "CLAIM_APPROVED";
            case "reject" -> "CLAIM_REJECTED";
            case "resettle" -> "CLAIM_RESETTLED";
            case "void" -> "CLAIM_VOIDED";
            case "delete" -> "CLAIM_DELETED";
            case "restore" -> "CLAIM_RESTORED";
            default -> throw new IllegalStateException("Unknown claim action: " + input.action() + ".");
        };
        boolean resettled = input.action().equals("resettle");
        boolean reversed = input.action().equals("void") && loaded.status() == ClaimStatus.SETTLED;
        boolean settled = "SETTLED".equals(saved.status()) && !resettled;
        String number = saved.number() != null ? saved.number() : loaded.number();
        audit.record(event + " sheet=" + loaded.sheetId() + " by=" + input.user()
                + " person=" + person.name() + " amount=" + saved.amount() + " date=" + saved.date()
                + (number != null ? " number=" + number : "")
                + (settled ? " due=" + (saved.settledDue() != null ? saved.settledDue() : "n/a") : "")
                + (input.reason() != null && !input.action().equals("void") ? " reason=" + input.reason() : "")
                + (resettled ? " old=" + (loaded.settledDue() != null ? loaded.settledDue() : "n/a")
                        + " new=" + (saved.settledDue() != null ? saved.settledDue() : "n/a") : "")
                + (reversed ? " reversed=" + (loaded.settledDue() != null ? loaded.settledDue() : "n/a") : "")
                + (input.reason() != null && input.action().equals("void") ? " reason=" + input.reason() : ""));
        if (event.equals("CLAIM_SETTLED") || event.equals("CLAIM_APPROVED") || event.equals("CLAIM_RESETTLED")) {
            for (String watcher : watches.watchers(loaded.sheetId(), loaded.personId())) {
                audit.record("NOTIFY sheet=" + loaded.sheetId() + " by=" + input.user() + " user=" + watcher
                        + " person=" + person.name() + " number=" + number);
            }
        }
    }

    /** The claim as an OPEN claim bound by no statement and not yet settled, for re-settling it at today's
     *  figure. */
    private static Claim asOpenUnstated(Claim c) {
        return new Claim(c.id(), c.sheetId(), c.personId(), c.amount(), c.date(), c.note(), ClaimStatus.OPEN,
                c.number(), null, c.openedBy(), false, null, c.corrects(), c.dueBy(), null, c.proofs(), c.splitFrom(), c.lateEntry(), c.reminded(), c.ref(), c.tags());
    }

    /** The claim's due now, as its row shows it: the figure a statement bound it to, else live (amount times its
     *  person's grade rate in force on the claim's date, divided by 100, rounded to two decimals as the claim rounds), with
     *  the late charge on it as of the sheet's today added, at least the sheet's floor in force on its date; null
     *  when it has no figure. */
    /** Why the claim cannot be opened as it is: its note is empty and its due is above the sheet's note threshold
     *  in force on its date; null when it may be opened. */
    static String noteRequired(Claim claim, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) {
        if (claim.note() != null && !claim.note().isBlank()) {
            return null;
        }
        BigDecimal threshold = settings.noteThreshold(claim.sheetId()).on(claim.date());
        if (threshold == null) {
            return null;
        }
        BigDecimal due = dueNow(claim, claims, people, rates, settings, sheets);
        if (due == null || due.compareTo(threshold) <= 0) {
            return null;
        }
        return "This claim's due " + due + " is above the note threshold " + threshold
                + "; give it a note before it is opened.";
    }

    private static BigDecimal dueNow(Claim claim, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) {
        var person = people.find(claim.sheetId(), claim.personId());
        return Dues.shown(claim, person.grades(), rates, settings.floor(claim.sheetId()),
                LateCharge.of(claim.sheetId(), settings, sheets, claims, people));
    }
}
package net.officefloor.hq.app.setting;


/** A sheet's permission matrix: for each action the roles that may take it, as a comma separated list ('' when
 *  blank: the standing rule applies — open, settle, void and close by clerk and steward; reassign and reopen by
 *  steward). */
public record Permissions(Map<String, String> roles) {

    /** The actions the matrix covers, in order. */
    public static final List<String> ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");

    /** The standing rule for each action, used while its entry is blank. */
    private static final Map<String, List<String>> STANDING = Map.of(
            "open", List.of(Role.CLERK, Role.STEWARD), "settle", List.of(Role.CLERK, Role.STEWARD),
            "void", List.of(Role.CLERK, Role.STEWARD), "close", List.of(Role.CLERK, Role.STEWARD),
            "reassign", List.of(Role.STEWARD), "reopen", List.of(Role.STEWARD));

    /** The entry for each action, in order ('' when blank). */
    public Map<String, String> entries() {
        Map<String, String> entries = new LinkedHashMap<>();
        for (String action : ACTIONS) {
            entries.put(action, roles.getOrDefault(action, ""));
        }
        return entries;
    }

    /** Whether the role may take the action. */
    public boolean allows(String action, String role) {
        String entry = roles.getOrDefault(action, "");
        List<String> allowed = entry.isBlank() ? STANDING.getOrDefault(action, List.of())
                : Arrays.stream(entry.split(",")).map(String::trim).toList();
        return allowed.contains(role);
    }
}

